41	export class MainSceneRig {
42	  private _sceneShake: SceneShake | null = null;
43	  private _sceneShakeEngine: Engine | null = null;
44	
45	  compose(state: MainTheatreState): SceneFromState {
46	    return {
47	      camera: {
48	        position: { ...state.camera.position },
49	        fov: state.camera.fov,
50	      },
51	      cameraTarget: {
52	        position: { ...state.camera.target },
53	      },
54	      [rocketId]: state.rocket,
55	      [jetEngineId]: {
56	        position: { ...state.jetEngine.position },
57	        rotation: { ...state.jetEngine.rotation },
58	        scale: { ...state.jetEngine.scale },
59	        visible: state.jetEngine.visible,
60	      },
61	      [groundId]: state.ground,
62	      [planetId]: state.planet,
63	      [earthId]: state.earth,
64	      [terrianId]: state.terrian,
65	      [windowId]: state.window,
66	      [backgroundId]: state.background,
67	      [cloudId]: state.cloud,
68	      [cloud2Id]: state.cloud2,
69	      [cloud3Id]: state.cloud3,
70	      [cloud4Id]: state.cloud4,
71	      [cloud5Id]: state.cloud5,
72	      [cloud6Id]: state.cloud6,
73	      [sceneLightsId]: state.sceneLights,
74	    } as unknown as SceneFromState;
75	  }
76	
77	  apply(engine: Engine, state: MainTheatreState): void {
78	    engine.setState(this.compose(state));
79	    this._applyRocket(engine, state.rocket);
80	    this._applyJetEngine(engine, state.jetEngine);
81	    this._applyPostProcessing(engine, state.postProcessing);
82	    this._applySceneLights(engine, state.sceneLights);
83	    this._applySceneShake(engine, state.sceneShake);
84	  }
85	
86	  read(engine: Engine): MainTheatreState {
87	    const camera = engine.getCamera();
88	    const target = engine.getCameraTarget();
89	    const defaults = DEFAULT_MAIN_SCENE_STATE;
90	    return {
91	      camera: {
92	        position: {
93	          x: this._toFinite(camera.position.x, defaults.camera.position.x),
94	          y: this._toFinite(camera.position.y, defaults.camera.position.y),
95	          z: this._toFinite(camera.position.z, defaults.camera.position.z),
96	        },
97	        target: {
98	          x: this._toFinite(target.position.x, defaults.camera.target.x),
99	          y: this._toFinite(target.position.y, defaults.camera.target.y),
100	          z: this._toFinite(target.position.z, defaults.camera.target.z),
101	        },
102	        fov: this._toFinite(camera.fov, defaults.camera.fov),
103	      },
104	      rocket: this._readRocket(engine),
105	      jetEngine: this._readJetEngine(engine),
106	      ground: this._readTransform(engine, groundId),
107	      planet: this._readTransform(engine, planetId),
108	      earth: this._readTransform(engine, earthId),
109	      terrian: this._readTransform(engine, terrianId),
110	      window: this._readTransform(engine, windowId),
111	      background: this._readBackground(engine),
112	      cloud: this._readCloud(engine),
113	      cloud2: this._readCloudById(engine, cloud2Id, defaults.cloud2),
114	      cloud3: this._readCloudById(engine, cloud3Id, defaults.cloud3),
115	      cloud4: this._readCloudById(engine, cloud4Id, defaults.cloud4),
116	      cloud5: this._readCloudById(engine, cloud5Id, defaults.cloud5),
117	      cloud6: this._readCloudById(engine, cloud6Id, defaults.cloud6),
118	      postProcessing: this._readPostProcessing(engine),
119	      sceneLights: this._readSceneLights(engine),
120	      sceneShake: this._readSceneShake(),
121	    };
122	  }
123	
124	  private _readTransform(engine: Engine, id: string): MainTransformState {
125	    const object = engine.getObjectById(id) as THREE.Object3D | null;
126	    const rotation = Helpers.readRotationDeg(object);
127	    return {
128	      position: {
129	        x: this._toFinite(object?.position.x, 0),
130	        y: this._toFinite(object?.position.y, 0),
131	        z: this._toFinite(object?.position.z, 0),
132	      },
133	      rotation: {
134	        x: this._toFinite(rotation.x, 0),
135	        y: this._toFinite(rotation.y, 0),
136	        z: this._toFinite(rotation.z, 0),
137	      },
138	      scale: {
139	        x: this._toFinite(object?.scale.x, 1),
140	        y: this._toFinite(object?.scale.y, 1),
141	        z: this._toFinite(object?.scale.z, 1),
142	      },
143	      visible: object?.visible ?? true,
144	    };
145	  }
146	
147	  private _readRocket(engine: Engine): MainRocketState {
148	    const transform = this._readTransform(engine, rocketId);
149	    const defaults = DEFAULT_MAIN_SCENE_STATE.rocket;
150	    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
151	    return {
152	      ...transform,
153	      flame: rocket?.getFlameState() ?? defaults.flame,
154	    };
155	  }
156	
157	  private _applyRocket(engine: Engine, state: MainRocketState): void {
158	    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
159	    if (!rocket) return;
160	    rocket.setFlameState(state.flame);
161	  }
162	
163	  private _applyJetEngine(engine: Engine, state: MainJetEngineState): void {
164	    const jet = engine.getSceneObjectById(jetEngineId) as SceneObject<
165	      JetEngineTweenProps
166	    > | null;
167	    if (!jet || typeof jet.setTimelineVars !== "function") return;
168	    const { position: _p, rotation: _r, scale: _s, ...rest } = state;
169	    jet.setTimelineVars(rest, "to");
170	  }
171	
172	  private _readJetEngine(engine: Engine): MainJetEngineState {
173	    const transform = this._readTransform(engine, jetEngineId);
174	    const defaults = DEFAULT_MAIN_SCENE_STATE.jetEngine;
175	    const object = engine.getSceneObjectById(jetEngineId) as
176	      | { getRuntimeOptions?: () => Record<string, unknown> }
177	      | null;
178	    const runtime = object?.getRuntimeOptions?.() ?? {};
179	    return {
180	      ...transform,
181	      intensity: this._toFinite(runtime.intensity, defaults.intensity),
182	      length: this._toFinite(runtime.length, defaults.length),
183	      nozzleRadius: this._toFinite(runtime.nozzleRadius, defaults.nozzleRadius),
184	      nozzleGap: this._toFinite(runtime.nozzleGap, defaults.nozzleGap),
185	      noise: this._toFinite(runtime.noise, defaults.noise),
186	      bloom: this._toFinite(runtime.bloom, defaults.bloom),
187	    };
188	  }
189	
190	  private _readBackground(engine: Engine): MainBackgroundState {
191	    const transform = this._readTransform(engine, backgroundId);
192	    const defaults = DEFAULT_MAIN_SCENE_STATE.background;
193	    const object = engine.getSceneObjectById(backgroundId) as
194	      | { getRuntimeOptions?: () => Record<string, unknown> }
195	      | null;
196	    const runtimeOptions = object?.getRuntimeOptions?.() ?? {};
197	    const look = runtimeOptions.look as Record<string, unknown> | undefined;
198	    return {
199	      ...transform,
200	      exposure: this._toFinite(runtimeOptions.exposure, defaults.exposure),
201	      look: {
202	        topColor: this._toFinite(look?.topColor, defaults.look.topColor),
203	        bottomColor: this._toFinite(
204	          look?.bottomColor,
205	          defaults.look.bottomColor,
206	        ),
207	        accentColor: this._toFinite(
208	          look?.accentColor,
209	          defaults.look.accentColor,
210	        ),
211	        starIntensity: this._toFinite(
212	          look?.starIntensity,
213	          defaults.look.starIntensity,
214	        ),
215	        starDensity: this._toFinite(look?.starDensity, defaults.look.starDensity),
216	        nebulaStrength: this._toFinite(
217	          look?.nebulaStrength,
218	          defaults.look.nebulaStrength,
219	        ),
220	        motionStrength: this._toFinite(
221	          look?.motionStrength,
222	          defaults.look.motionStrength,
223	        ),
224	        legacyMix: this._toFinite(look?.legacyMix, defaults.look.legacyMix),
225	      },
226	    };
227	  }
228	
229	  private _readCloud(engine: Engine): MainCloudState {
230	    return this._readCloudById(engine, cloudId, DEFAULT_MAIN_SCENE_STATE.cloud);
231	  }
232	
233	  private _readCloudById(
234	    engine: Engine,
235	    id: string,
236	    defaults: MainCloudState,
237	  ): MainCloudState {
238	    const transform = this._readTransform(engine, id);
239	    const object = engine.getSceneObjectById(id) as
240	      | { getRuntimeOptions?: () => Record<string, unknown> }
241	      | null;
242	    const runtimeOptions = object?.getRuntimeOptions?.() ?? {};
243	    return {
244	      ...transform,
245	      chapter: this._toFinite(runtimeOptions.chapter, defaults.chapter),
246	      transition: this._toFinite(
247	        runtimeOptions.transition,
248	        defaults.transition,
249	      ),
250	    };
251	  }
252	
253	  private _readPostProcessing(engine: Engine): MainPostProcessingState {
254	    const defaults = DEFAULT_MAIN_SCENE_STATE.postProcessing;
255	    const postProcessor = engine.getPostProcessor();
256	    const renderer = engine.getRenderer() as
257	      | { toneMappingExposure?: number }
258	      | null;
259	    const bloom = postProcessor?.getBloomOptions();
260	    const vignette = postProcessor?.getVignetteOptions();
261	    return {
262	      bloom: {
263	        strength: this._toFinite(bloom?.strength, defaults.bloom.strength),
264	        radius: this._toFinite(bloom?.radius, defaults.bloom.radius),
265	        threshold: this._toFinite(bloom?.threshold, defaults.bloom.threshold),
266	        compositeStrength: this._toFinite(
267	          bloom?.compositeStrength,
268	          defaults.bloom.compositeStrength,
269	        ),
270	      },
271	      vignette: {
272	        offset: this._toFinite(vignette?.offset, defaults.vignette.offset),
273	        darkness: this._toFinite(
274	          vignette?.darkness,
275	          defaults.vignette.darkness,
276	        ),
277	      },
278	      exposure: this._toFinite(
279	        renderer?.toneMappingExposure,
280	        defaults.exposure,
281	      ),
282	    };
283	  }
284	
285	  private _readSceneLights(engine: Engine): MainSceneLightsState {
286	    const sceneLights = engine.getSceneObjectById(
287	      sceneLightsId,
288	    ) as MainSceneLightsPort | null;
289	    if (sceneLights) {
290	      return sceneLights.getState();
291	    }
292	    const defaults = DEFAULT_MAIN_SCENE_STATE.sceneLights;
293	    return {
294	      visible: defaults.visible,
295	      intensity: defaults.intensity,
296	      flightProgress: defaults.flightProgress,
297	      groundLight: defaults.groundLight,
298	      rocketFillLight: defaults.rocketFillLight,
299	      rocketRimLightLeft: defaults.rocketRimLightLeft,
300	      rocketRimLightRight: defaults.rocketRimLightRight,
301	      ground: this._readTransform(engine, groundId),
302	    };
303	  }
304	
305	  private _applySceneLights(engine: Engine, state: MainSceneLightsState): void {
306	    const sceneLights = engine.getSceneObjectById(
307	      sceneLightsId,
308	    ) as MainSceneLightsPort | null;
309	    if (!sceneLights) return;
310	    sceneLights.setState(state);
311	  }
312	
313	  private _applyPostProcessing(
314	    engine: Engine,
315	    state: MainPostProcessingState,
316	  ): void {
317	    const postProcessor = engine.getPostProcessor();
318	    postProcessor?.setBloomOptions(state.bloom);
319	    postProcessor?.setVignetteOptions(state.vignette);
320	    const renderer = engine.getRenderer() as
321	      | { toneMappingExposure?: number }
322	      | null;
323	    if (!renderer || typeof renderer.toneMappingExposure !== "number") return;
324	    renderer.toneMappingExposure = this._toFinite(
325	      state.exposure,
326	      DEFAULT_MAIN_SCENE_STATE.postProcessing.exposure,
327	    );
328	  }
329	
330	  private _readSceneShake(): MainSceneShakeState {
331	    return DEFAULT_MAIN_SCENE_STATE.sceneShake;
332	  }
333	
334	  private _applySceneShake(
335	    engine: Engine,
336	    state: MainSceneShakeState,
337	  ): void {
338	    const gsap = this._getGsap();
339	    if (!gsap) return;
340	
341	    const sceneShake = this._ensureSceneShake(engine, gsap);
342	    if (!sceneShake) return;
343	    sceneShake.setState(state);
344	    sceneShake.runApply();
345	  }
346	
347	  private _ensureSceneShake(
348	    engine: Engine,
349	    gsap: GsapGlobal,
350	  ): SceneShake | null {
351	    if (this._sceneShake && this._sceneShakeEngine === engine) {
352	      return this._sceneShake;
353	    }
354	    this._sceneShake?.offShake();
355	    this._sceneShake = new SceneShake(
356	      engine.getCamera(),
357	      engine.getCameraTarget(),
358	      gsap,
359	    );
360	    this._sceneShakeEngine = engine;
361	    return this._sceneShake;
362	  }
363	
364	  private _getGsap(): GsapGlobal | null {
365	    if (typeof window === "undefined") return null;
366	    return ((window as WindowWithGsap).gsap ?? null) as GsapGlobal | null;
367	  }
368	
369	  private _toFinite(value: unknown, fallback: number): number {
370	    if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
371	    return value;
372	  }
373	}
