262	  private _readJetEngine(engine: Engine): MainJetEngineState {
263	    const transform = this._readTransform(
264	      engine,
265	      jetEngineId,
266	      CONTACT_DEFAULT_SCENE_STATE.jetEngine,
267	    );
268	    const defaults = CONTACT_DEFAULT_SCENE_STATE.jetEngine;
269	    const object = engine.getSceneObjectById(jetEngineId) as
270	      | { getRuntimeOptions?: () => Record<string, unknown> }
271	      | null;
272	    const runtime = object?.getRuntimeOptions?.() ?? {};
273	    return {
274	      ...transform,
275	      intensity: this._toFinite(runtime.intensity, defaults.intensity),
276	      length: this._toFinite(runtime.length, defaults.length),
277	      nozzleRadius: this._toFinite(runtime.nozzleRadius, defaults.nozzleRadius),
278	      nozzleGap: this._toFinite(runtime.nozzleGap, defaults.nozzleGap),
279	      noise: this._toFinite(runtime.noise, defaults.noise),
