290	
291	  private _readTransform(
292	    engine: Engine,
293	    id: string,
294	    fallback: ContactTransformState,
295	  ): ContactTransformState {
296	    const target = engine.getObjectById(id) as THREE.Object3D | null;
297	    const rotation = Helpers.readRotationDeg(target);
298	    return {
299	      position: {
300	        x: this._toFinite(target?.position.x, fallback.position.x),
301	        y: this._toFinite(target?.position.y, fallback.position.y),
302	        z: this._toFinite(target?.position.z, fallback.position.z),
303	      },
304	      rotation: {
305	        x: this._toFinite(rotation.x, fallback.rotation.x),
306	        y: this._toFinite(rotation.y, fallback.rotation.y),
307	        z: this._toFinite(rotation.z, fallback.rotation.z),
308	      },
309	      scale: {
310	        x: this._toFinite(target?.scale.x, fallback.scale.x),
311	        y: this._toFinite(target?.scale.y, fallback.scale.y),
312	        z: this._toFinite(target?.scale.z, fallback.scale.z),
313	      },
314	      visible: target?.visible ?? fallback.visible,
315	    };
316	  }
317	
318	  private _toFinite(value: unknown, fallback: number): number {
319	    if (typeof value !== "number") return fallback;
320	    if (!Number.isFinite(value)) return fallback;
321	    return value;
322	  }
323	}
