29	const FADE_START_SCALE = 0.65;
30	const SMOKE_Z_DRIFT = 0.002;
31	const SMOKE_SPREAD = 1.005;
32	const MIN_INIT_SCALE = 0.4;
33	const MAX_INIT_SCALE = 1.0;
34	const LIFETIME_TICKS = 150;
35	
36	const DEFAULT_TEXTURE_URLS = [
37	  "/resource/images/texture/smoke/smoke_01.png",
38	  "/resource/images/texture/rocket/smoke.png",
39	];
40	
41	const DEFAULTS = {
42	  attachTo: "rocket",
43	  spawnOffset: { x: 0 as number, y: -0.34 as number, z: 0 as number },
44	  colors: ["#FFFFFF", "#F5F5F5", "#EEEEEE"] as string[],
45	  dotsPerInterval: 3,
46	  physicsScale: 0.006,
47	};
