95	  override runUpdate(delta: number): void {
96	    const ctx = this._context;
97	    if (!ctx || this._disposed) return;
98	
99	    this._accumMs += delta * 1000;
100	    if (this._accumMs >= 15) {
101	      this._accumMs -= 15;
102	      this._tick(ctx);
103	    }
104	  }
105	
106	  private _tick(ctx: SceneObjectContext): void {
107	    const o = this._resolve();
108	
109	    if (o.attachTo) {
110	      const rkt = ctx.getObject(o.attachTo);
111	      if (rkt instanceof THREE.Object3D) {
112	        rkt.getWorldPosition(this._spawnPt);
113	        this._spawnPt.x += o.spawnOffset.x ?? 0;
114	        this._spawnPt.y += o.spawnOffset.y ?? 0;
115	        this._spawnPt.z += o.spawnOffset.z ?? 0;
116	      }
117	    }
118	
119	    for (let i = 0; i < o.dotsPerInterval; i++) this._spawn(ctx, o);
120	
121	    const dead: number[] = [];
122	    this._balls.forEach((b, id) => { if (this._step(b)) dead.push(id); });
123	    for (const id of dead) this._balls.delete(id);
124	  }
125	
126	  private _spawn(ctx: SceneObjectContext, o: ResolvedOpts): void {
127	    if (this._baseMats.length === 0) return;
128	
129	    const s = o.physicsScale;
130	    const baseMat = this._baseMats[Math.floor(Math.random() * this._baseMats.length)];
131	    const mat = baseMat.clone();
132	
133	    const color = o.colors[this._rnd(0, o.colors.length)] ?? o.colors[0];
134	    mat.color.set(color);
135	    mat.rotation = Math.random() * Math.PI * 2;
136	
137	    const initScale = MIN_INIT_SCALE + Math.random() * (MAX_INIT_SCALE - MIN_INIT_SCALE);
138	    const shrinkRate = -(initScale - 0.1) / LIFETIME_TICKS;
139	
140	    const isXNeg = this._rnd(1, 2) === 1;
141	    const isZNeg = this._rnd(1, 2) === 1;
142	
143	    const sprite = new THREE.Sprite(mat);
144	    sprite.scale.setScalar(initScale);
145	
146	    const info: SphereInfo = {
147	      ID: ++this._idx,
148	      startX: this._spawnPt.x,
149	      startY: this._spawnPt.y,
150	      startZ: this._spawnPt.z,
151	      vx: isXNeg ? this._rnd(0, 50) * -0.15 * s : this._rnd(0, 50) * 0.15 * s,
152	      vy: this._rnd(-10, 20) * s,
153	      vz: isZNeg ? this._rnd(-25, 25) * -0.4 * s : this._rnd(-25, 25) * 0.4 * s,
154	      gravity: 10 * s,
155	      rotDir: (Math.random() < 0.5 ? 1 : -1) * (0.003 + Math.random() * 0.006),
156	      shrinkRate,
157	      sphere: sprite,
158	      material: mat,
159	    };
160	
161	    ctx.scene.add(sprite);
162	    this._balls.set(info.ID, info);
163	  }
164	
165	  private _step(b: SphereInfo): boolean {
166	    const sp = b.sphere;
167	
168	    sp.scale.x += b.shrinkRate;
169	    sp.scale.y += b.shrinkRate;
170	
171	    b.startX += b.vx * 0.6;
172	    b.startY -= b.vy * 0.5;
173	    b.startZ -= b.vz * 0.6;
174	    sp.position.x = b.startX;
175	    sp.position.y = b.startY;
176	    sp.position.z = b.startZ;
177	
178	    b.vy += b.gravity;
179	    b.material.rotation += b.rotDir;
180	
181	    if (sp.scale.y < FADE_START_SCALE) {
182	      b.material.opacity = Math.max(0, (sp.scale.y - 0.1) / (FADE_START_SCALE - 0.1));
183	      sp.position.z -= SMOKE_Z_DRIFT;
184	      b.startX *= SMOKE_SPREAD;
185	      b.startY *= SMOKE_SPREAD;
186	    }
187	
188	    if (sp.scale.y <= 0.1) {
189	      this._context?.scene.remove(sp);
190	      b.material.dispose();
191	      return true;
192	    }
193	    return false;
194	  }
195	
196	  protected override applyVisibility(visible: boolean): void {
197	    this._balls.forEach(b => { b.sphere.visible = visible; });
198	  }
199	
200	  override dispose(): void {
201	    if (this._disposed) return;
202	    const scene = this._context?.scene;
203	
204	    this._balls.forEach(b => {
205	      scene?.remove(b.sphere);
206	      b.material.dispose();
207	    });
208	    this._balls.clear();
209	
210	    for (const mat of this._baseMats) mat.dispose();
211	    this._baseMats = [];
212	
213	    super.dispose();
214	  }
215	
216	  private _resolve(): ResolvedOpts {
217	    const o = this._opts;
218	    return {
219	      attachTo: o.attachTo ?? DEFAULTS.attachTo,
220	      spawnOffset: o.spawnOffset ?? DEFAULTS.spawnOffset,
221	      colors: (o.colors && o.colors.length > 0) ? o.colors : DEFAULTS.colors,
222	      dotsPerInterval: o.dotsPerInterval ?? DEFAULTS.dotsPerInterval,
223	      physicsScale: o.physicsScale ?? DEFAULTS.physicsScale,
224	    };
225	  }
226	
227	  private _rnd(min: number, max: number): number {
228	    return Math.floor(Math.random() * max) + min;
229	  }
230	}
