288	const _portfolioHoverCleanups: Array<() => void> = [];
289	
290	(function initPortfolioHover(): void {
291	  const items = document.querySelectorAll<HTMLLIElement>(
292	    ".no-main-portfolio__item[data-video]",
293	  );
294	  items.forEach((li) => {
295	    const videoUrl = li.dataset.video || MAIN_PORTFOLIO_FALLBACK_VIDEO;
296	    const figure = li.querySelector<HTMLElement>(".no-sub-gallery-item__img");
297	    const video = li.querySelector<HTMLVideoElement>("video");
298	    if (!figure || !video) return;
299	
300	    let isHovered = false;
301	    let pendingPlay: Promise<void> | null = null;
302	
303	    const show = (): void => {
304	      if (isHovered) figure.classList.add("is-video-active");
305	    };
306	    const hideNow = (): void => {
307	      figure.classList.remove("is-video-active");
308	    };
309	    const safePause = (): void => {
310	      video.pause();
311	      video.currentTime = 0;
312	    };
313	    const drainAndPause = (): void => {
314	      const p = pendingPlay;
315	      pendingPlay = null;
316	      if (p !== null) {
317	        void p.then(() => {
318	          if (!isHovered) safePause();
319	        });
320	      } else {
321	        safePause();
322	      }
323	    };
324	
325	    const onEnter = (): void => {
326	      isHovered = true;
327	      if (!video.src) {
328	        video.src = videoUrl;
329	        video.load();
330	      }
331	      pendingPlay = video.play().catch(() => undefined);
332	      if (video.readyState >= 3) {
333	        show();
334	      } else {
335	        video.addEventListener("canplay", show, { once: true });
336	      }
337	    };
338	    const onLeave = (): void => {
339	      isHovered = false;
340	      video.removeEventListener("canplay", show);
341	      hideNow();
342	      drainAndPause();
343	    };
344	
345	    li.addEventListener("pointerenter", onEnter);
346	    li.addEventListener("pointerleave", onLeave);
347	    _portfolioHoverCleanups.push(() => {
348	      isHovered = false;
349	      video.removeEventListener("canplay", show);
350	      figure.classList.remove("is-video-active");
351	      drainAndPause();
352	      li.removeEventListener("pointerenter", onEnter);
353	      li.removeEventListener("pointerleave", onLeave);
354	    });
355	  });
356	})();
