#### **Step 4: GravityBalls.ts에서 사용**

```typescript
export class GravityBalls extends SceneObject<GravityBallsTweenProps> {
  // ... 기존 코드 ...

  private _tick(ctx: SceneObjectContext): void {
    const o = this._resolve();

    // dotsPerInterval는 이미 사용 중 (라인 119)
    for (let i = 0; i < o.dotsPerInterval; i++) this._spawn(ctx, o);

    const dead: number[] = [];
    this._balls.forEach((b, id) => { if (this._step(b, o)) dead.push(id); });
    for (const id of dead) this._balls.delete(id);
  }

  private _step(b: SphereInfo, o: ResolvedOpts): boolean {
    const sp = b.sphere;

    // speed prop 적용 (기본 1.0배수)
    const speedMult = (this._opts.speed ?? 1.0);

    sp.scale.x += b.shrinkRate * speedMult;
    sp.scale.y += b.shrinkRate * speedMult;

    b.startX += b.vx * 0.6 * speedMult;
    b.startY -= b.vy * 0.5 * speedMult;
    b.startZ -= b.vz * 0.6 * speedMult;
    sp.position.x = b.startX;
    sp.position.y = b.startY;
    sp.position.z = b.startZ;

    b.vy += b.gravity * speedMult;
    // ... 나머지 ...
  }
}
```

#### **Step 5: MainSceneRig에 apply/read 메서드 추가** (선택사항)

만약 GravityBalls를 Theatre에서 주요 제어 대상으로 두려면:

```typescript
// MainSceneRig.ts에 추가
private _applyGravityBalls(
  engine: Engine,
  state: { speed?: number; dotsPerInterval?: number; visible?: boolean },
): void {
  const gb = engine.getSceneObjectById(gravityBallsId) as SceneObject<
    GravityBallsTweenProps
  > | null;
  if (!gb || typeof gb.setTimelineVars !== "function") return;
  gb.setTimelineVars(state, "to");
}

private _readGravityBalls(engine: Engine): {
  speed?: number;
  dotsPerInterval?: number;
  visible?: boolean;
} {
  const gb = engine.getSceneObjectById(gravityBallsId) as
    | { getRuntimeOptions?: () => Record<string, unknown> }
    | null;
  const runtime = gb?.getRuntimeOptions?.() ?? {};
  return {
    speed: this._toFinite(runtime.speed, 1.0),
    dotsPerInterval: this._toFinite(runtime.dotsPerInterval, 50),
    visible: (runtime.visible as boolean) ?? true,
  };
}
```

